package com.bank.spark.model;

// A join side with a compile-time estimate and a measured runtime size.
public class JoinStage {
    private final String side;
    private final long estimatedBytes;        // known at plan time (pre-filter)
    private final long runtimeBytesAfterFilter; // measured after the stage runs

    public JoinStage(String side, long estimatedBytes, long runtimeBytesAfterFilter) {
        this.side = side;
        this.estimatedBytes = estimatedBytes;
        this.runtimeBytesAfterFilter = runtimeBytesAfterFilter;
    }

    public String getSide() { return side; }
    public long getEstimatedBytes() { return estimatedBytes; }
    public long getRuntimeBytesAfterFilter() { return runtimeBytesAfterFilter; }
}
