package com.bank.spark.service;

import com.bank.spark.model.JoinStage;

// Simulates AQE's runtime re-optimization of the join strategy.
public class AqeReoptimizer {

    private final long aqeBroadcastThreshold;

    public AqeReoptimizer(long aqeBroadcastThreshold) {
        this.aqeBroadcastThreshold = aqeBroadcastThreshold;
    }

    // Static planner uses the estimate.
    public String staticPlan(JoinStage s) {
        return s.getEstimatedBytes() <= aqeBroadcastThreshold
                ? "BroadcastHashJoin (estimate already small)"
                : "SortMergeJoin (estimate " + mb(s.getEstimatedBytes()) + " > threshold)";
    }

    // AQE re-plans using the MEASURED runtime size at the stage boundary.
    public String aqePlan(JoinStage s) {
        if (s.getRuntimeBytesAfterFilter() <= aqeBroadcastThreshold) {
            return "SWITCH to BroadcastHashJoin (runtime " + mb(s.getRuntimeBytesAfterFilter())
                    + " <= threshold) + local shuffle reader on large side";
        }
        return "keep SortMergeJoin (runtime " + mb(s.getRuntimeBytesAfterFilter()) + " still large)";
    }

    private String mb(long bytes) { return (bytes / (1024 * 1024)) + " MB"; }
}
