package com.bank.spark;

import com.bank.spark.model.JoinStage;
import com.bank.spark.service.AqeReoptimizer;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class AqeJoinSwitchDemo {

    private static final Logger log = Logger.getLogger(AqeJoinSwitchDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AqeReoptimizer aqe = new AqeReoptimizer(10L * 1024 * 1024); // 10 MB

        // Product dimension: 50 MB estimated, 3 MB after filtering to active products.
        JoinStage products = new JoinStage("products (active only)", 50L * 1024 * 1024, 3L * 1024 * 1024);

        log.info("STATIC plan (before run): " + aqe.staticPlan(products));
        log.info("...filter stage runs, AQE reads real shuffle size at the stage boundary...");
        log.info("AQE plan (runtime): " + aqe.aqePlan(products));
        log.info("Result: sort+merge on the huge transactions table avoided; small side broadcast instead.");

        // Counter-case: a side that stays large after filtering — AQE keeps sort-merge.
        JoinStage accounts = new JoinStage("accounts", 8_000L * 1024 * 1024, 6_000L * 1024 * 1024);
        log.info("STATIC plan: " + aqe.staticPlan(accounts));
        log.warning("AQE plan: " + aqe.aqePlan(accounts));
    }
}

